import{_ as t,C as a,c as r,o as e,a0 as n,b as i,w as l,a as o,G as s,a1 as d}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Workshop: Avancerad mental spelsession (3-4 timmar)","description":"","frontmatter":{},"headers":[],"relativePath":"sv/workshop.md","filePath":"sv/workshop.md"}');const u=t({name:"sv/workshop.md"},[["render",function(t,g,u,m,k,p){const h=a("Mermaid");return e(),r("div",null,[g[4]||(g[4]=n('<h1 id="workshop-avancerad-mental-spelsession-3-4-timmar" tabindex="-1">Workshop: Avancerad mental spelsession (3-4 timmar) <a class="header-anchor" href="#workshop-avancerad-mental-spelsession-3-4-timmar" aria-label="Permalink to &quot;Workshop: Avancerad mental spelsession (3-4 timmar)&quot;">​</a></h1><h2 id="oversikt" tabindex="-1">Översikt <a class="header-anchor" href="#oversikt" aria-label="Permalink to &quot;Översikt&quot;">​</a></h2><p>Denna workshop är en avancerad teoretisk session på 3–4 timmar för 6–8 elitspelare, med fokus på djuppsykologiskt arbete och sårbarhetsbaserat lärande. Den går utöver grundläggande mentala färdigheter för att utforska det inre spelet på en djupgående nivå.</p><div class="tip custom-block"><p class="custom-block-title">Två avsnitt i den här guiden</p><ul><li><strong><a href="#för-deltagare">För deltagare</a></strong> - Vad spelarna kommer att uppleva och lära sig</li><li><strong><a href="#för-handledare">För handledare</a></strong> - Hur man leder workshopen som koordinator för mental prestation</li></ul></div><p><strong>Skillnad från nybörjarpass:</strong></p><ul><li><strong>Nybörjare (2-3 timmar):</strong> Introduktion till mentala spelkoncept → <a href="/sv/mental-journey/sessionsguide">Se guiden för den mentala resan</a></li><li><strong>Avancerad (3-4 timmar):</strong> Djupgående psykologiskt arbete med sårbarhetsövningar (denna sida)</li></ul><h2 id="snabbatkomst" tabindex="-1">Snabbåtkomst <a class="header-anchor" href="#snabbatkomst" aria-label="Permalink to &quot;Snabbåtkomst&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Avsnitt</th><th>Ändamål</th><th>Tillträde</th></tr></thead><tbody><tr><td><strong>För deltagare</strong></td><td>Vad man kan förvänta sig och hur man förbereder sig</td><td><a href="#för-deltagare">Visa avsnitt</a></td></tr><tr><td><strong>För handledare</strong></td><td>Komplett sessionsguide och övningar</td><td><a href="#för-handledare">Visa avsnitt</a></td></tr><tr><td><strong>Material för sessionen</strong></td><td>Övningar och arbetsblad</td><td><a href="#material-för-handledare">Visa material</a></td></tr><tr><td><strong>Relaterade guider</strong></td><td>Andra träningsformat</td><td><a href="/sv/mental-resa/">Mental resa</a> • <a href="/sv/träningsläger">Träningsläger</a></td></tr></tbody></table><hr><h2 id="for-deltagare" tabindex="-1">För deltagare <a class="header-anchor" href="#for-deltagare" aria-label="Permalink to &quot;För deltagare&quot;">​</a></h2><h3 id="vad-man-kan-forvanta-sig" tabindex="-1">Vad man kan förvänta sig <a class="header-anchor" href="#vad-man-kan-forvanta-sig" aria-label="Permalink to &quot;Vad man kan förvänta sig&quot;">​</a></h3><p>Detta är inte ett typiskt träningspass. Du kommer att delta i djupa diskussioner om de mentala och emotionella aspekterna av boule som sällan diskuteras öppet.</p><p><strong>Denna workshop är:</strong></p><ul><li>✅ En trygg plats att utforska inre tankar och rädslor</li><li>✅ Sårbarhetsbaserat lärande med lagkamrater</li><li>✅ Koppla mentala mönster till prestation</li><li>✅ Bygga teamets psykologiska intelligens</li></ul><p><strong>Denna workshop är INTE:</strong></p><ul><li>❌ Teknisk coachning eller taktikträning</li><li>❌ Terapi eller rådgivning</li><li>❌ Positivt tänkande eller motivationstal</li><li>❌ Omdöme eller kritik</li></ul><h3 id="sessionsstruktur" tabindex="-1">Sessionsstruktur <a class="header-anchor" href="#sessionsstruktur" aria-label="Permalink to &quot;Sessionsstruktur&quot;">​</a></h3>',17)),(e(),i(d,null,{default:l(()=>[s(h,{id:"mermaid-165",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWorkshopsession%5D%20--%3E%20B%5BGrundl%C3%A4ggning%2060%20min%5D%0A%20%20%20%20B%20--%3E%20C%5BDjupg%C3%A5ende%20arbete%2090%20min%5D%0A%20%20%20%20C%20--%3E%20D%5BIntegration%2045%20min%5D%0A%20%20%20%20D%20--%3E%20E%5BSt%C3%A4nger%2015%20min%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23ffe4e1%0A%20%20%20%20style%20D%20fill%3A%23e3f2fd%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:l(()=>[...g[0]||(g[0]=[o(" Loading... ",-1)])]),_:1})),g[5]||(g[5]=n('<p><strong>Total längd:</strong> 3–4 timmar <strong>Gruppstorlek:</strong> 6–8 spelare <strong>Format:</strong> Cirkeldiskussion med strukturerade övningar</p><h3 id="vad-du-kommer-att-lara-dig" tabindex="-1">Vad du kommer att lära dig <a class="header-anchor" href="#vad-du-kommer-att-lara-dig" aria-label="Permalink to &quot;Vad du kommer att lära dig&quot;">​</a></h3><h4 id="fas-1-grundlaggning-60-min" tabindex="-1">Fas 1: Grundläggning (60 min) <a class="header-anchor" href="#fas-1-grundlaggning-60-min" aria-label="Permalink to &quot;Fas 1: Grundläggning (60 min)&quot;">​</a></h4><ul><li>Grundregler för psykologisk säkerhet</li><li>&quot;Incheckningsmatrisen&quot; - bekräftar ditt nuvarande tillstånd</li><li>&quot;Pétanquens isberg&quot; - utforskar dolda tankar</li></ul><h4 id="fas-2-djupgaende-arbete-90-min" tabindex="-1">Fas 2: Djupgående arbete (90 min) <a class="header-anchor" href="#fas-2-djupgaende-arbete-90-min" aria-label="Permalink to &quot;Fas 2: Djupgående arbete (90 min)&quot;">​</a></h4><ul><li>Skapa din &quot;Användarmanual&quot; för lagkamrater</li><li>Koppla mentala mönster till prestation</li><li>&quot;Rädsla i en hatt&quot; - att bryta isolering genom gemensam sårbarhet</li></ul><h4 id="fas-3-integration-45-min" tabindex="-1">Fas 3: Integration (45 min) <a class="header-anchor" href="#fas-3-integration-45-min" aria-label="Permalink to &quot;Fas 3: Integration (45 min)&quot;">​</a></h4><ul><li>Omformulera din inre kritiker till inre coach</li><li>Skapa lagprotokoll för tävling</li><li>Praktiska tips för pisten</li></ul><h4 id="fas-4-avslutning-15-min" tabindex="-1">Fas 4: Avslutning (15 min) <a class="header-anchor" href="#fas-4-avslutning-15-min" aria-label="Permalink to &quot;Fas 4: Avslutning (15 min)&quot;">​</a></h4><ul><li>Reflektion och engagemang</li><li>Uppföljningsstöd</li></ul><h3 id="grundregler" tabindex="-1">Grundregler <a class="header-anchor" href="#grundregler" aria-label="Permalink to &quot;Grundregler&quot;">​</a></h3><p>Innan sessionen börjar är alla deltagare överens om att:</p><div class="tip custom-block"><p class="custom-block-title">Behållaren - Viktiga grundregler</p><ol><li><strong>Sekretess</strong> - Det som sägs här, stannar här</li><li><strong>Vegasregeln</strong> - Lektionerna lämnar rummet, berättelserna stannar</li><li><strong>Ingen reparation</strong> - Bevittna och förstå, försök inte lösa</li><li><strong>Rätt att passera</strong> - Sårbarhet kan inte tvingas fram</li><li><strong>Respektera processen</strong> - Lita på obehaget</li></ol></div><h3 id="vad-man-ska-ta-med-sig" tabindex="-1">Vad man ska ta med sig <a class="header-anchor" href="#vad-man-ska-ta-med-sig" aria-label="Permalink to &quot;Vad man ska ta med sig&quot;">​</a></h3><p><strong>Nödvändig:</strong></p><ul><li>Öppet sinne och vilja att dela med sig</li><li>Dina egna erfarenheter och utmaningar</li><li>Respekt för andras sårbarhet</li></ul><p><strong>Frivillig:</strong></p><ul><li>Anteckningsbok för personliga reflektioner</li><li>Frågor om specifika psykiska utmaningar</li></ul><h3 id="viktiga-aktiviteter-du-kommer-att-uppleva" tabindex="-1">Viktiga aktiviteter du kommer att uppleva <a class="header-anchor" href="#viktiga-aktiviteter-du-kommer-att-uppleva" aria-label="Permalink to &quot;Viktiga aktiviteter du kommer att uppleva&quot;">​</a></h3><h4 id="incheckningsmatrisen" tabindex="-1">Incheckningsmatrisen <a class="header-anchor" href="#incheckningsmatrisen" aria-label="Permalink to &quot;Incheckningsmatrisen&quot;">​</a></h4><p>Placera dig själv på ett rutnät av energi och humör. Normalisera att vi alla har olika tillstånd.</p><h4 id="bouleis-isberg" tabindex="-1">Bouleis isberg <a class="header-anchor" href="#bouleis-isberg" aria-label="Permalink to &quot;Bouleis isberg&quot;">​</a></h4><p>Utforska vad som händer under ytan – tankarna och rädslorna som ingen ser.</p><h4 id="anvandarmanualen" tabindex="-1">Användarmanualen <a class="header-anchor" href="#anvandarmanualen" aria-label="Permalink to &quot;Användarmanualen&quot;">​</a></h4><p>Skapa en bruksanvisning för dig själv så att dina lagkamrater förstår hur de kan stödja dig.</p><h4 id="radsla-i-en-hatt" tabindex="-1">Rädsla i en hatt <a class="header-anchor" href="#radsla-i-en-hatt" aria-label="Permalink to &quot;Rädsla i en hatt&quot;">​</a></h4><p>Dela djupa rädslor anonymt och hör dem bekräftas av jämnåriga. Bryt isoleringen.</p><h4 id="inre-kritikerns-omformulering" tabindex="-1">Inre kritikerns omformulering <a class="header-anchor" href="#inre-kritikerns-omformulering" aria-label="Permalink to &quot;Inre kritikerns omformulering&quot;">​</a></h4><p>Förvandla hårt självprat till stödjande coachande språk.</p><h3 id="efter-workshopen" tabindex="-1">Efter workshopen <a class="header-anchor" href="#efter-workshopen" aria-label="Permalink to &quot;Efter workshopen&quot;">​</a></h3><p>Du kommer att åka därifrån med:</p><ul><li>Djupare förståelse för dina mentala mönster</li><li>Teamprotokoll för att stödja varandra</li><li>Omformulerade fraser för den inre coachen</li><li>Kontakt med lagkamrater genom delad sårbarhet</li><li>Användbara verktyg för tävling</li></ul><div class="warning custom-block"><p class="custom-block-title">Sårbarhetsbaksmälla</p><p>Efter djupgående delning kan du känna dig avslöjad eller ångerfull. Detta är normalt. Handledaren kommer att höra av sig till dig inom 24 timmar. Kom ihåg: det du delade hjälpte alla.</p></div><hr><h2 id="for-handledare" tabindex="-1">För handledare <a class="header-anchor" href="#for-handledare" aria-label="Permalink to &quot;För handledare&quot;">​</a></h2><h3 id="din-roll-som-koordinator-for-mental-prestation" tabindex="-1">Din roll som koordinator för mental prestation <a class="header-anchor" href="#din-roll-som-koordinator-for-mental-prestation" aria-label="Permalink to &quot;Din roll som koordinator för mental prestation&quot;">​</a></h3><p>Som <strong>Mental Performance Coordinator (MPC)</strong> underlättar du djupa diskussioner om det mentala spelet och skapar psykologisk trygghet som leder till prestation i pisten.</p><div class="warning custom-block"><p class="custom-block-title">Kritiskt koncept</p><p><strong>Du är inte en teknisk tränare eller terapeut.</strong> Din roll är att underlätta sårbarhetsbaserat lärande som hjälper spelare att förstå sambandet mellan deras inre tankar och deras prestation.</p></div><h3 id="dina-ansvarsomraden" tabindex="-1">Dina ansvarsområden <a class="header-anchor" href="#dina-ansvarsomraden" aria-label="Permalink to &quot;Dina ansvarsområden&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Viktiga ansvarsområden</p><ul><li><strong>Facilitera, föreläs inte</strong> - Du leder diskussionen, lär inte ut teknik</li><li><strong>Håll utrymmet</strong> - Skapa och upprätthåll psykologisk trygghet</li><li><strong>Brygga teori till praktik</strong> - Koppla webbplatsinnehåll till inre upplevelse</li><li><strong>Övervaka gruppdynamiken</strong> - Lägg märke till vilka som är engagerade och vilka som är motståndare</li><li><strong>Upprätthåll gränser</strong> - Vet när du ska söka professionell hjälp</li></ul></div><h3 id="forberedelser-infor-workshopen" tabindex="-1">Förberedelser inför workshopen <a class="header-anchor" href="#forberedelser-infor-workshopen" aria-label="Permalink to &quot;Förberedelser inför workshopen&quot;">​</a></h3><h3 id="viktiga-kompetenser" tabindex="-1">Viktiga kompetenser <a class="header-anchor" href="#viktiga-kompetenser" aria-label="Permalink to &quot;Viktiga kompetenser&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kompetens</th><th>Vad det betyder</th><th>Hur man utvecklar</th></tr></thead><tbody><tr><td><strong>Emotionell intelligens</strong></td><td>Upptäck mikrouttryck av obehag</td><td>Öva aktiv observation</td></tr><tr><td><strong>Neutral auktoritet</strong></td><td>Befå respekt utan teknisk makt</td><td>Skapa trovärdighet genom närvaro</td></tr><tr><td><strong>Sportkontext</strong></td><td>Förstå tryckmekanik</td><td>Lär dig bouleterminologi och kultur</td></tr><tr><td><strong>Verbal Aikido</strong></td><td>Anpassa dig till motståndet, bekämpa det inte</td><td>Öva på icke-defensiv kommunikation</td></tr></tbody></table><details class="details custom-block"><summary>Viktiga bouletermer att känna till</summary><ul><li><strong>Carreau</strong> - Perfekt skott som förskjuter motståndarens klot</li><li><strong>Bibber</strong> - &quot;Jippen&quot; - ofrivillig tremor vid utlösning</li><li><strong>Donnée</strong> - Det &quot;givna&quot; - att acceptera terrängen som den är</li><li><strong>Portée</strong> - Kast utan studs</li><li><strong>Roulette</strong> - Rullande skott</li><li><strong>Cochonnet</strong> - Målbollen (jack)</li></ul></details><h2 id="fysisk-uppstallning-den-magiska-cirkeln" tabindex="-1">Fysisk uppställning: Den magiska cirkeln <a class="header-anchor" href="#fysisk-uppstallning-den-magiska-cirkeln" aria-label="Permalink to &quot;Fysisk uppställning: Den magiska cirkeln&quot;">​</a></h2><h3 id="platskrav" tabindex="-1">Platskrav <a class="header-anchor" href="#platskrav" aria-label="Permalink to &quot;Platskrav&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Kritisk inställning</p><p><strong>Välj ett neutralt utrymme BORTA från pisten.</strong> Detta signalerar en övergång från fysiskt till mentalt arbete.</p><p>Krav:</p><ul><li>✅ Ljudisolerat eller privat</li><li>✅ Bekväm temperatur</li><li>✅ Inga distraktioner (telefoner avstängda)</li><li>✅ Naturligt ljus om möjligt</li><li>✅ Separat från träningsområdet</li></ul></div><h3 id="cirkelkonfigurationen" tabindex="-1">Cirkelkonfigurationen <a class="header-anchor" href="#cirkelkonfigurationen" aria-label="Permalink to &quot;Cirkelkonfigurationen&quot;">​</a></h3><p><strong>Sittplatser:</strong></p><ul><li>Perfekt cirkel av stolar</li><li><strong>INGA BORD</strong> - Bord skapar barriärer och döljer kroppsspråk</li><li>Alla stolar i samma höjd (inga elpositioner)</li><li>Koordinatorn sitter som en del av cirkeln (inte längst fram)</li></ul><p><strong>Centrala artefakter:</strong></p><ul><li>Placera boule och cochonett i mitten</li><li>Förankrar arbetet i sporten</li><li>Visuell påminnelse om gemensamt syfte</li></ul>',52)),(e(),i(d,null,{default:l(()=>[s(h,{id:"mermaid-628",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFysiskt%20utrymme%5D%20--%3E%20B%5BSignalerar%20mental%20f%C3%B6r%C3%A4ndring%5D%0A%20%20%20%20A%20--%3E%20C%5BInga%20hinder%5D%0A%20%20%20%20A%20--%3E%20D%5BLika%20positionering%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BPsykologisk%20s%C3%A4kerhet%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:l(()=>[...g[1]||(g[1]=[o(" Loading... ",-1)])]),_:1})),g[6]||(g[6]=n('<h2 id="sessionsstruktur-3–4-timmar" tabindex="-1">Sessionsstruktur (3–4 timmar) <a class="header-anchor" href="#sessionsstruktur-3–4-timmar" aria-label="Permalink to &quot;Sessionsstruktur (3–4 timmar)&quot;">​</a></h2><h3 id="fas-1-grundlaggning-60-minuter" tabindex="-1">Fas 1: Grundläggning (60 minuter) <a class="header-anchor" href="#fas-1-grundlaggning-60-minuter" aria-label="Permalink to &quot;Fas 1: Grundläggning (60 minuter)&quot;">​</a></h3><h4 id="_1-valkommen-och-grundregler-15-min" tabindex="-1">1. Välkommen och grundregler (15 min) <a class="header-anchor" href="#_1-valkommen-och-grundregler-15-min" aria-label="Permalink to &quot;1. Välkommen och grundregler (15 min)&quot;">​</a></h4><p><strong>Det sociala kontraktet:</strong></p><div class="tip custom-block"><p class="custom-block-title">Behållaren - Viktiga grundregler</p><p>Innan någon delning påbörjas MÅSTE gruppen komma överens om att:</p><ol><li><strong>Sekretess</strong> - Det som sägs här, stannar här</li><li><strong>Vegasregeln</strong> - Lektionerna lämnar rummet, berättelserna stannar</li><li><strong>Ingen reparation</strong> - Bevittna och förstå, försök inte lösa</li><li><strong>Rätt att passera</strong> - Sårbarhet kan inte tvingas fram</li><li><strong>Respektera processen</strong> - Lita på obehaget</li></ol></div><p><strong>Ditt manus:</strong></p><blockquote><p>&quot;Välkommen. Det här utrymmet är annorlunda än pisten. Här utforskar vi vad som händer <em>inuti</em> när du står över den där bilden. Allt som delas här är konfidentiellt. Lärdomarna du får kan försvinna, men de personliga berättelserna stannar kvar. Ni är inte här för att fixa varandra – bara för att förstå. Och ni kan alltid låta bli. Kan alla komma överens om detta?&quot;</p></blockquote><h4 id="_2-aktivitet-incheckningsmatrisen-20-min" tabindex="-1">2. Aktivitet: Incheckningsmatrisen (20 min) <a class="header-anchor" href="#_2-aktivitet-incheckningsmatrisen-20-min" aria-label="Permalink to &quot;2. Aktivitet: Incheckningsmatrisen (20 min)&quot;">​</a></h4><p><strong>Mål:</strong> Normalisera att erkänna trötthet eller stress</p><p><strong>Material:</strong> Whiteboard eller flipchart, självhäftande lappar</p><p><strong>Förfarande:</strong></p><ol><li>Rita 2x2-matris: Hög/låg energi (vertikal), Positiv/negativ (horisontell)</li><li>Varje spelare skriver sitt namn på en lapp</li><li>Placera anteckningen i deras nuvarande kvadrant</li><li>Diskutera: &quot;Vi har tre personer i &#39;Låg energi/negativ&#39;. Hur påverkar detta vår session idag?&quot;</li></ol>',12)),(e(),i(d,null,{default:l(()=>[s(h,{id:"mermaid-715",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BIncheckningsmatris%5D%20--%3E%20B%5BH%C3%B6g%20energi%20%2B%20positiv%5D%0A%20%20%20%20A%20--%3E%20C%5BH%C3%B6g%20energi%20%2B%20negativ%5D%0A%20%20%20%20A%20--%3E%20D%5BL%C3%A5g%20energi%20%2B%20Positiv%5D%0A%20%20%20%20A%20--%3E%20E%5BL%C3%A5g%20energi%20%2B%20negativ%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BErk%C3%A4nn%20alla%20stater%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:l(()=>[...g[2]||(g[2]=[o(" Loading... ",-1)])]),_:1})),g[7]||(g[7]=n('<p><strong>Tips för facilitering:</strong></p><ul><li>Döm inte någon kvadrant som &quot;dålig&quot;</li><li>Fråga: &quot;Vad behöver din kropp just nu?&quot;</li><li>Lägg märke till mönster: &quot;Tre av er är i samma utrymme - vad handlar det om?&quot;</li></ul><h4 id="_3-aktivitet-bouleisberget-25-min" tabindex="-1">3. Aktivitet: Bouleisberget (25 min) <a class="header-anchor" href="#_3-aktivitet-bouleisberget-25-min" aria-label="Permalink to &quot;3. Aktivitet: Bouleisberget (25 min)&quot;">​</a></h4><p><strong>Mål:</strong> Visualisera dolda inre tankar</p><p><strong>Material:</strong> Stort papper, tuschpennor</p><p><strong>Förfarande:</strong></p><ol><li>Rita isberg på papper</li><li><strong>Ovanför vattenytan:</strong> Skriv &quot;Teknik, Kastet, Resultatet&quot;</li><li><strong>Nedan vattenytan:</strong> Fråga: &quot;Vad händer i ditt sinne som ingen ser?&quot;</li></ol><p><strong>Uppmaningar:</strong></p><ul><li>&quot;Vad är du rädd för när du kliver fram för att skjuta?&quot;</li><li>&quot;Vilket omdöme oroar du dig för?&quot;</li><li>&quot;Vad säger din inre röst när du missar?&quot;</li></ul><p><strong>Insiktsfrågan:</strong></p><blockquote><p>&quot;Vad händer med din kastarm när &#39;undervattens&#39;grejerna blir för tunga?&quot;</p></blockquote><p>Detta kopplar mental belastning till fysisk spänning (pipandet/yipset).</p><details class="details custom-block"><summary>Vanliga svar på &quot;under vattenytan&quot;</summary><ul><li>Rädsla för att svika laget</li><li>Oroa dig för att se dum ut</li><li>Tvivel om förmåga</li><li>Jämförelse med andra</li><li>Press att bevisa sitt värde</li><li>Rädsla för att bli dömd av tränare/lagkamrater</li><li>Impostorsyndrom</li></ul></details><h3 id="fas-2-djupgaende-arbete-90-minuter" tabindex="-1">Fas 2: Djupgående arbete (90 minuter) <a class="header-anchor" href="#fas-2-djupgaende-arbete-90-minuter" aria-label="Permalink to &quot;Fas 2: Djupgående arbete (90 minuter)&quot;">​</a></h3><h4 id="_4-aktivitet-bruksanvisningen-30-min" tabindex="-1">4. Aktivitet: Bruksanvisningen (30 min) <a class="header-anchor" href="#_4-aktivitet-bruksanvisningen-30-min" aria-label="Permalink to &quot;4. Aktivitet: Bruksanvisningen (30 min)&quot;">​</a></h4><p><strong>Mål:</strong> Operationalisera empati - hjälpa lagkamrater att förstå varandra</p><p><strong>Material:</strong> Arbetsblad (ett per spelare)</p><p><strong>Mallen för användarmanualen:</strong></p><table tabindex="0"><thead><tr><th>Avsnitt</th><th>Prompt</th><th>Exempel</th></tr></thead><tbody><tr><td><strong>Min stresssignatur</strong></td><td>&quot;När jag är orolig, jag...&quot;</td><td>&quot;...bli helt tyst&quot;</td></tr><tr><td><strong>Hur man hanterar mig</strong></td><td>&quot;När jag missar ett avgörande skott behöver jag...&quot;</td><td>&quot;...tystnad, inte uppmuntran&quot;</td></tr><tr><td><strong>Min inre tanke</strong></td><td>&quot;Lögnen jag berättar för mig själv är...&quot;</td><td>&quot;...att jag inte är tillräckligt bra&quot;</td></tr><tr><td><strong>Min utlösare</strong></td><td>&quot;Jag blir defensiv när...&quot;</td><td>&quot;...någon ifrågasätter mitt val av skott&quot;</td></tr></tbody></table><p><strong>Förfarande:</strong></p><ol><li>Ge spelarna 10 minuter att slutföra i tystnad</li><li>Gå runt cirkeln - varje person delar EN sektion</li><li>Andra kan ställa förtydligande frågor (inte råd!).</li><li>Koordinatorn validerar varje delning</li></ol><p><strong>Manus för handledning:</strong></p><blockquote><p>&quot;Detta är din bruksanvisning. När din lagkamrat vet att du tystnar när du är orolig, kommer de inte att ta det personligt. När de vet att du behöver tystnad efter en miss, kommer de inte att försöka &#39;fixa&#39; dig. Det är så vi bygger teamintelligens.&quot;</p></blockquote><h4 id="_5-att-koppla-webbplatsinnehall-till-inre-tankar-30-min" tabindex="-1">5. Att koppla webbplatsinnehåll till inre tankar (30 min) <a class="header-anchor" href="#_5-att-koppla-webbplatsinnehall-till-inre-tankar-30-min" aria-label="Permalink to &quot;5. Att koppla webbplatsinnehåll till inre tankar (30 min)&quot;">​</a></h4><p><strong>Mål:</strong> Koppla samman tekniskt innehåll med psykologisk upplevelse</p><p>Välj 2–3 sektioner från Akademins webbplats och utforska det inre spelet:</p><p><strong>Exempel 1: Teknik - Grepp och Släpp</strong></p><p><strong>Frågan om förtroende:</strong></p><blockquote><p>&quot;När du har 12-12 i en turnering, <em>känns</em> din hand som teknikbeskrivningen? Är det musklerna som förändras eller tanken &#39;Tappa den inte&#39; som förändrar ditt grepp?&quot;</p></blockquote><p><strong>Mikrotremorn:</strong></p><blockquote><p>&quot;Vem här känner av ångestens &#39;mikrotremor&#39;? Vilken inre tanke utlöser det?&quot;</p></blockquote><p><strong>Exempel 2: Taktik - Pekning kontra skjutning</strong></p><p><strong>Riskprofil:</strong></p><blockquote><p>&quot;När guiden säger &#39;Skjut för att vinna&#39;, är din reaktion spänning eller rädsla? Vad säger det dig om din relation till risk?&quot;</p></blockquote><p><strong>Bedragaren:</strong></p><blockquote><p>&quot;Pekar du någonsin när du <em>vet</em> att du borde skjuta, bara för att undvika pinsamheten att missa? Vad kostar den säkerheten?&quot;</p></blockquote><p><strong>Exempel 3: Näring - Tävlingsdag</strong></p><p><strong>Komfortmatsfällan:</strong></p><blockquote><p>&quot;Äter du vad din kropp behöver eller vad din ångest vill ha? Hur vet du skillnaden?&quot;</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Faciliteringsteknik</p><p>Föreläs inte om innehållet. Ställ frågor som kopplar den tekniska informationen till deras levda erfarenhet. Insikten kommer från DEM, inte från dig.</p></div><h4 id="_6-aktivitet-radsla-i-en-hatt-30-min" tabindex="-1">6. Aktivitet: Rädsla i en hatt (30 min) <a class="header-anchor" href="#_6-aktivitet-radsla-i-en-hatt-30-min" aria-label="Permalink to &quot;6. Aktivitet: Rädsla i en hatt (30 min)&quot;">​</a></h4><p><strong>Mål:</strong> Bryt isoleringsslingan – visa att jämnåriga delar djupa osäkerheter</p><p><strong>Material:</strong> Papper, penna, hatt/väska</p><p><strong>Förfarande:</strong></p><ol><li>Alla skriver anonymt om djup karriär-/lagrädsla</li><li>Vik papper och blanda i hatten</li><li>Varje spelare drar en lapp (inte sin egen)</li><li>Läs det högt</li><li>Bekräfta det: &quot;Jag kan förstå varför någon skulle känna så här eftersom...&quot;</li></ol><p><strong>Exempel på rädslor:</strong></p><ul><li>&quot;Jag är rädd att jag har nått toppen och aldrig kommer att bli bättre&quot;</li><li>&quot;Jag är orolig att mina lagkamrater tycker att jag är överskattad&quot;</li><li>&quot;Jag är rädd att jag kommer att kvävas i det stora ögonblicket&quot;</li><li>&quot;Jag är rädd för att bli ersatt av yngre spelare&quot;</li></ul><p><strong>Kraften:</strong> När spelarna hör sin hemliga rädsla läsas högt och bekräftas av jämnåriga, försvinner skammen. De inser: &quot;Jag är inte ensam. Det här är normalt.&quot;</p><p><strong>Koordinatorns roll:</strong></p><ul><li>Validera VARJE rädsla som legitim</li><li>Minimera inte: &quot;Det är inte sant!&quot; ogiltigförklarar känslan.</li><li>Fråga: &quot;Hur många av er har känt något liknande?&quot;</li></ul>',50)),(e(),i(d,null,{default:l(()=>[s(h,{id:"mermaid-1094",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BR%C3%A4dsla%20i%20en%20hatt%5D%20--%3E%20B%5BAnonym%20delning%5D%0A%20%20%20%20B%20--%3E%20C%5BPeer-validering%5D%0A%20%20%20%20C%20--%3E%20D%5BSkam%20uppl%C3%B6ses%5D%0A%20%20%20%20D%20--%3E%20E%5BIsoleringsbrytningar%5D%0A%20%20%20%20E%20--%3E%20F%5BPsykologisk%20s%C3%A4kerhet%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffe4e1%0A%20%20%20%20style%20F%20fill%3A%23e8f5e9%0A"})]),fallback:l(()=>[...g[3]||(g[3]=[o(" Loading... ",-1)])]),_:1})),g[8]||(g[8]=n('<h3 id="fas-3-integration-45-minuter" tabindex="-1">Fas 3: Integration (45 minuter) <a class="header-anchor" href="#fas-3-integration-45-minuter" aria-label="Permalink to &quot;Fas 3: Integration (45 minuter)&quot;">​</a></h3><h4 id="_7-aktivitet-att-omformulera-den-inre-kritikern-25-min" tabindex="-1">7. Aktivitet: Att omformulera den inre kritikern (25 min) <a class="header-anchor" href="#_7-aktivitet-att-omformulera-den-inre-kritikern-25-min" aria-label="Permalink to &quot;7. Aktivitet: Att omformulera den inre kritikern (25 min)&quot;">​</a></h4><p><strong>Mål:</strong> Kognitiv omstrukturering - förändra den interna dialogen</p><p><strong>Material:</strong> Arbetsblad</p><p><strong>Förfarande:</strong></p><p><strong>Steg 1: Identifiera kritikern (10 min)</strong></p><blockquote><p>&quot;Skriv ner EXAKT den fras din inre kritiker säger efter en miss. Inte den artiga versionen – den brutala.&quot;</p></blockquote><p>Exempel:</p><ul><li>&quot;Du kvävs alltid&quot;</li><li>&quot;Alla ser dig misslyckas&quot;</li><li>&quot;Du skämmer ut dig själv&quot;</li><li>&quot;Du hör inte hemma här&quot;</li></ul><p><strong>Steg 2: Omformulera som inre coach (10 min)</strong></p><blockquote><p>&quot;Skriv nu om det som din inre coach – bestämd men stödjande.&quot;</p></blockquote><p>Exempel:</p><ul><li>Kritiker: &quot;Du kvävs alltid&quot; → Tränare: &quot;Återställ och andas. Nästa skott.&quot;</li><li>Kritiker: &quot;Alla ser dig misslyckas&quot; → Tränare: &quot;Fokusera på målet, inte publiken&quot;</li><li>Kritiker: &quot;Du skämmer ut dig själv&quot; → Tränare: &quot;En chans i taget. Du har gjort det här förut.&quot;</li></ul><p><strong>Steg 3: Partnerövning (5 min)</strong></p><blockquote><p>&quot;Dela din Coach-fras med en partner. De kommer att påminna dig om den när de ser Kritikern komma fram.&quot;</p></blockquote><h4 id="_8-bro-till-pisten-20-min" tabindex="-1">8. Bro till pisten (20 min) <a class="header-anchor" href="#_8-bro-till-pisten-20-min" aria-label="Permalink to &quot;8. Bro till pisten (20 min)&quot;">​</a></h4><p><strong>Mål:</strong> Skapa handlingsbara protokoll för tävling</p><p><strong>Diskussionsfrågor:</strong></p><ol><li>&quot;Vad är EN sak från idag som du kommer att använda i din nästa tävling?&quot;</li><li>&quot;Hur kommer dina lagkamrater att veta att du behöver stöd?&quot;</li><li>&quot;Vad är din signal för &#39;Jag behöver en mental återställning&#39;?&quot;</li></ol><p><strong>Skapa teamprotokoll:</strong></p><table tabindex="0"><thead><tr><th>Situation</th><th>Protokoll</th><th>Exempel</th></tr></thead><tbody><tr><td><strong>Efter en miss</strong></td><td>Kontrollera användarmanualen</td><td>&quot;Marc behöver tystnad, Lisa behöver en knytnäve.&quot;</td></tr><tr><td><strong>Känner press</strong></td><td>Använd Coach-frasen</td><td>&quot;Återställ och andas&quot;</td></tr><tr><td><strong>Spänning i laget</strong></td><td>Samtalstidsgräns</td><td>&quot;Låt oss ta 2 minuter&quot;</td></tr><tr><td><strong>Inre kritiker högljudd</strong></td><td>Fysisk återställning</td><td>Rör boule, djupt andetag</td></tr></tbody></table><h3 id="fas-4-avslutning-15-minuter" tabindex="-1">Fas 4: Avslutning (15 minuter) <a class="header-anchor" href="#fas-4-avslutning-15-minuter" aria-label="Permalink to &quot;Fas 4: Avslutning (15 minuter)&quot;">​</a></h3><h4 id="_9-utcheckningen-10-min" tabindex="-1">9. Utcheckningen (10 min) <a class="header-anchor" href="#_9-utcheckningen-10-min" aria-label="Permalink to &quot;9. Utcheckningen (10 min)&quot;">​</a></h4><p><strong>Förfarande:</strong> Gå runt i cirkeln, varje person delar:</p><ol><li><strong>En sak du tar med dig:</strong> &quot;Vilken insikt eller vilket verktyg har du kvar?&quot;</li><li><strong>En sak du lämnar bakom dig:</strong> &quot;Vad släpper du taget om?&quot;</li></ol><p><strong>Koordinatorns roll:</strong></p><ul><li>Tacka varje person för deras bidrag</li><li>Validera det utförda arbetet</li><li>Påminn om sekretessen</li></ul><h4 id="_10-uppfoljningsprotokoll-5-min" tabindex="-1">10. Uppföljningsprotokoll (5 min) <a class="header-anchor" href="#_10-uppfoljningsprotokoll-5-min" aria-label="Permalink to &quot;10. Uppföljningsprotokoll (5 min)&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Kritiskt: Förhindra sårbarhetsbaksmälla</p><p>Djupt arbete orsakar en &quot;sårbarhetsbaksmälla&quot; - ånger eller skam över att dela med sig.</p><p><strong>Ditt 24-timmarsprotokoll:</strong></p><ul><li>Sms:a alla som delat flitigt inom 24 timmar</li><li>Meddelande: &quot;Tack för ditt mod igår. Det du delade hjälpte alla.&quot;</li><li>Checka in: &quot;Hur känner du dig inför sessionen?&quot;</li></ul></div><p><strong>Avslutningsmanus:</strong></p><blockquote><p>&quot;Det som hände här idag krävde mod. Du dök upp, du öppnade upp dig, du litade på processen. Samma mod är vad du kommer att ta med dig till pisten. Kom ihåg: lärdomarna lämnar det här rummet, men berättelserna stannar kvar. Tack.&quot;</p></blockquote><h2 id="hantering-av-motstand" tabindex="-1">Hantering av motstånd <a class="header-anchor" href="#hantering-av-motstand" aria-label="Permalink to &quot;Hantering av motstånd&quot;">​</a></h2><h3 id="den-quot-for-coola-quot-atleten" tabindex="-1">Den &quot;för coola&quot; atleten <a class="header-anchor" href="#den-quot-for-coola-quot-atleten" aria-label="Permalink to &quot;Den &amp;quot;för coola&amp;quot; atleten&quot;">​</a></h3><p><strong>Scenario:</strong> En spelare himlar med ögonen åt en sårbarhetsövning</p><p><strong>Strategi:</strong> Verbal Aikido (Align and Pivot)</p><p><strong>Manus:</strong></p><blockquote><p>&quot;Jag förstår den reaktionen, [Namn]. Ärligt talat, jag förstår det. Att prata om känslor känns mjukt. Men pisten är obekväm. Om vi inte klarar av obehaget i det här rummet, tränar vi inte vår tolerans för obehaget i spelet. Kan du lita på mig i 20 minuter?&quot;</p></blockquote><h3 id="den-tysta-deltagaren" tabindex="-1">Den tysta deltagaren <a class="header-anchor" href="#den-tysta-deltagaren" aria-label="Permalink to &quot;Den tysta deltagaren&quot;">​</a></h3><p><strong>Scenario:</strong> Någon har inte talat på 45 minuter</p><p><strong>Strategi:</strong> Skapa en ingångspunkt med låga insatser</p><p><strong>Manus:</strong></p><blockquote><p>&quot;[Namn], jag märker att du tar in allt. Finns det en sak som resonerar med dig hittills? Bara ett ord.&quot;</p></blockquote><h3 id="overdelaren" tabindex="-1">Överdelaren <a class="header-anchor" href="#overdelaren" aria-label="Permalink to &quot;Överdelaren&quot;">​</a></h3><p><strong>Scenario:</strong> Någon dominerar med långa berättelser</p><p><strong>Strategi:</strong> Skonsam omdirigering</p><p><strong>Manus:</strong></p><blockquote><p>&quot;Tack för det, [Namn]. Jag vill se till att alla har plats. Låt oss höra från någon som inte har delat än.&quot;</p></blockquote><h3 id="fixaren" tabindex="-1">Fixaren <a class="header-anchor" href="#fixaren" aria-label="Permalink to &quot;Fixaren&quot;">​</a></h3><p><strong>Scenario:</strong> Någon försöker lösa andras problem</p><p><strong>Strategi:</strong> Förstärk grundreglerna</p><p><strong>Manus:</strong></p><blockquote><p>&quot;Jag uppskattar att du vill hjälpa till, men kom ihåg vår regel: bevittna och förstå, laga inte. [Originaltalare], vad behöver du just nu?&quot;</p></blockquote><h2 id="materialchecklista" tabindex="-1">Materialchecklista <a class="header-anchor" href="#materialchecklista" aria-label="Permalink to &quot;Materialchecklista&quot;">​</a></h2><details class="details custom-block"><summary>Verkstadsmaterial</summary><p><strong>Fysisk uppställning:</strong></p><ul><li>[ ] Stolar (6-8, inga bord)</li><li>[ ] Boule och cochonett för center</li><li>[ ] Flipchart eller whiteboard</li><li>[ ] Markörer</li></ul><p><strong>Aktiviteter:</strong></p><ul><li>[ ] Fästisar (incheckningsmatris)</li><li>[ ] Stort papper (isbergsaktivitet)</li><li>[ ] Arbetsblad för användarmanualer</li><li>[ ] Papper och pennor (Rädsla i en hatt)</li><li>[ ] Arbetsblad för inre kritiker/coach</li></ul><p><strong>Logistik:</strong></p><ul><li>[ ] Vatten för deltagarna</li><li>[ ] Vävnader (känslomässigt arbete!)</li><li>[ ] Timer (håll schemat)</li><li>[ ] Deltagarnas kontaktlista (för uppföljning)</li></ul></details><h2 id="koordinator-for-egenvard" tabindex="-1">Koordinator för egenvård <a class="header-anchor" href="#koordinator-for-egenvard" aria-label="Permalink to &quot;Koordinator för egenvård&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Du behöver också stöd</p><p>Att ge plats åt sårbarhet är känslomässigt krävande.</p><p><strong>Efter workshopen:</strong></p><ul><li>Avrapportering med en kollega eller handledare</li><li>Dagbok om vad som hände dig</li><li>Ta en promenad eller fysisk paus</li><li>Bär inte med er deras berättelser hem</li></ul></div><h2 id="matning-av-effekt" tabindex="-1">Mätning av effekt <a class="header-anchor" href="#matning-av-effekt" aria-label="Permalink to &quot;Mätning av effekt&quot;">​</a></h2><h3 id="omedelbar-aterkoppling" tabindex="-1">Omedelbar återkoppling <a class="header-anchor" href="#omedelbar-aterkoppling" aria-label="Permalink to &quot;Omedelbar återkoppling&quot;">​</a></h3><p>Till sist, fråga:</p><ol><li>&quot;På en skala från 1–10, hur trygg kände du dig när du delade med dig idag?&quot;</li><li>&quot;Vad är en sak som skulle göra nästa session bättre?&quot;</li></ol><h3 id="langsiktig-sparning" tabindex="-1">Långsiktig spårning <a class="header-anchor" href="#langsiktig-sparning" aria-label="Permalink to &quot;Långsiktig spårning&quot;">​</a></h3><p>Uppföljning efter 2–4 veckor:</p><ul><li>&quot;Har du använt några verktyg från verkstaden?&quot;</li><li>&quot;Hur har din relation med din inre kritiker förändrats?&quot;</li><li>&quot;Vad är annorlunda i ditt tävlingsinställning?&quot;</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Bygga vidare på denna grund</p><p>Denna workshop är fas 1. Tänk på:</p><ul><li><strong>Uppföljningsmöten</strong> (online eller personligen)</li><li><strong>Integration i pisten</strong> (se guiden för träningspasset)</li><li><strong>Lagprotokoll</strong> (implementera användarmanualer i tävling)</li><li><strong>Individuella incheckningar</strong> (för spelare som behöver mer stöd)</li></ul></div>',65))])}]]);export{g as __pageData,u as default};
